class Batch:
    def __init__(self, name, items):
        self.name = name
        self.items = items

    def __str__(self):
        return f"Batch {self.name} ({len(self.items)} drums)"

    def __len__(self):
        return len(self.items)

    def __eq__(self, other):
        return self.items == other.items

b = Batch("B-101", ["D1", "D2", "D3"])
print(b)
print(len(b))
print(b == Batch("B-102", ["D1", "D2", "D3"]))

class MeanModel:
    def fit(self, y):
        self.mean_ = sum(y) / len(y)
        return self

    def predict(self, n):
        return [self.mean_] * n

model = MeanModel().fit([10, 20, 30])
print(model.mean_)
print(model.predict(2))

class Account:
    def __init__(self, balance):
        self.__balance = balance      # __ = private

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Invalid amount")
        self.__balance += amount

    @property
    def balance(self):
        return self.__balance

acc = Account(1000)
acc.deposit(500)
print(acc.balance)
try:
    print(acc.__balance)
except AttributeError:
    print("Private hai, bahar se nahi dikhta")

class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def info(self):
        return f"{self.name} earns {self.salary}"

class Manager(Employee):
    def __init__(self, name, salary, team_size):
        super().__init__(name, salary)
        self.team_size = team_size

    def team(self):
        return f"{self.name} manages {self.team_size} people"

m = Manager("Akash", 50000, 5)
print(m.info())
print(m.team())
print(isinstance(m, Employee))

