def count_up(n):
    i = 1
    while i <= n:
        yield i
        i += 1

for x in count_up(3):
    print(x)

def batches(data, size):
    for i in range(0, len(data), size):
        yield data[i:i + size]

for b in batches([1, 2, 3, 4, 5, 6, 7], 3):
    print(b)

def log(func):
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__}{args}")
        result = func(*args, **kwargs)
        print(f"Done -> {result}")
        return result
    return wrapper

@log
def add(a, b):
    return a + b

add(2, 3)

import functools

def count_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

@count_calls
def predict(x):
    return x * 2

predict(1); predict(2); predict(3)
print(predict.calls, predict.__name__)

