class NegativeReading(Exception):
    pass

def parse(value):
    x = float(value)
    if x < 0:
        raise NegativeReading(value)
    return x

raw = ["12.5", "abc", "7", "-4", "3.25", ""]
clean = []
bad = 0
for v in raw:
    try:
        clean.append(parse(v))
    except (ValueError, NegativeReading):
        bad += 1
print("Clean:", clean)
print("Bad:", bad)
print("Mean:", round(sum(clean) / len(clean), 2))
